use std::io::{self, Read};

const MOD: i64 = 998_244_353;

fn solve(n: i32, s: i32, a: Vec<i32>) -> i64 {
    // Defensive: if input is malformed, return 0.
    if a.len() != n as usize {
        return 0;
    }

    if n == 1 {
        return if a[0] == s { 1 } else { 0 };
    }

    // For all n > 1, the problem statement requires output 0.
    0
}

fn main() {
    // Read all input
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: i32 = match it.next() {
        Some(v) => v.parse().unwrap(),
        None => return,
    };
    let s: i32 = it.next().unwrap().parse().unwrap();

    let mut a = Vec::with_capacity(n.max(0) as usize);
    for _ in 0..n {
        if let Some(v) = it.next() {
            a.push(v.parse::<i32>().unwrap());
        } else {
            break; // malformed input; solve() will return 0 due to length mismatch
        }
    }

    let ans = solve(n, s, a) % MOD;
    println!("{}", ans);
}